/**
 * Persona voices (PLAN 5.8): a voice designed from a description, fixed by one reference clip.
 *
 *   voices/<id>.yaml          written by the user: description (+ optional reference sentences)
 *   voices/<id>/<lang>.wav    reference clip chosen with `s2v voice pick`
 *   voices/<id>/<lang>.json   how the clip was made (description, sentence, seed, model, hash)
 *
 * Synthesis clones the reference clip with the Qwen3-TTS Base model, so every sentence keeps the
 * same voice. The clip is generated by the VoiceDesign model and imitates no real person.
 */

import { parse as parseYaml } from 'yaml';
import { z } from 'zod';
import { LANGS, type Lang } from './schema.js';

export const PERSONA_ID = /^[a-z0-9][a-z0-9-]*$/;

export const personaSchema = z.object({
  /** Natural-language voice description passed to VoiceDesign (any language). */
  description: z.string().min(1).max(1000),
  /** Sentence the reference clip says, per language. Defaults to DEFAULT_REFERENCE. */
  reference: z.partialRecord(z.enum(LANGS), z.string().min(1).max(500)).default({}),
});
export type Persona = z.infer<typeof personaSchema>;

/** About 5–8 s of calm speech: enough for the clone prompt without a long, drifting clip. */
export const DEFAULT_REFERENCE: Record<Lang, string> = {
  ko: '안녕하세요. 오늘도 함께 이야기를 나눠 볼게요. 천천히, 또박또박 말씀드리겠습니다.',
  ja: 'こんにちは。今日も一緒にお話ししましょう。ゆっくり、はっきりとお伝えします。',
  en: "Hello, and welcome. Today we'll talk it through together, slowly and clearly.",
};

/** Metadata stored next to a reference clip (`voices/<id>/<lang>.json`). */
export interface PersonaClip {
  id: string;
  lang: Lang;
  description: string;
  text: string;
  seed: number;
  model: string;
  revision: string;
  /** sha256 of the wav file: part of every synthesis cache key. */
  sha256: string;
  candidate: number;
  /** Loudness the clip was leveled to (absent: not leveled). */
  lufs?: number;
  /** How the clip was finished from the raw VoiceDesign output (pauses, fades, end pad). */
  finish?: string;
  /** Reference checks it failed when it was a candidate (empty: passed). */
  gates?: string[];
  created: string;
}

export function parsePersona(source: string): Persona {
  return personaSchema.parse(parseYaml(source) ?? {});
}

export function referenceText(persona: Persona, lang: Lang): string {
  return persona.reference[lang] ?? DEFAULT_REFERENCE[lang];
}
